// core: no std::io, no clock, no println!
pub fn decide_charge(sub: &Subscription, now: i64) -> Option<Charge> {
    let monthly = match sub.tier {
        Tier::Free => return None,
        Tier::Pro  => 2900,
        Tier::Team => 9900,
    };
    let days = (now - sub.started_at).max(0);
    Some(Charge { amount_cents: monthly * days / 30 })
}
