pub enum Effect { Upsert(Resource), Delete(Id), Requeue(After) }
pub struct ReconcileResult { pub effects: Vec<Effect> }
pub fn reconcile(snap: &Snapshot, obj: &Resource) -> ReconcileResult {  // pure
    match snap.get(&obj.id) {
        Some(cur) if cur == obj => ReconcileResult { effects: vec![] },
        _ => ReconcileResult {
            effects: vec![Effect::Upsert(obj.clone()), Effect::Requeue(After::Secs(5))],
        },
    }
}
